(()=>{'use strict';
 const $=id=>document.getElementById(id), $$=(q,root=document)=>[...root.querySelectorAll(q)];
 const ICONS={restaurant:'🍽️',barber:'✂️',auto:'🏎️',retail:'🛍️'};
 const TITLES={overview:'Overview',requests:'Request center',catalog:'Catalog',stations:'QR stations',analytics:'Analytics',settings:'Experience studio',team:'Team access'};
 const ACTIONS={restaurant:[['💧','Request water','water'],['🙋','Call staff','service'],['🧾','Ask for bill','check'],['❔','Ask a question','question']],barber:[['📍','Check in','checkin'],['✂️','Ask for service','service'],['📅','Booking help','appointment'],['❔','Ask a question','question']],auto:[['🔧','Get an estimate','estimate'],['🚗','Vehicle drop-off','dropoff'],['🧽','Request service','service'],['❔','Ask a question','question']],retail:[['🙋','Get assistance','assistance'],['👟','Check a size','size'],['🛒','Checkout help','checkout'],['❔','Ask a question','question']]};
 const DEMO_SLUGS=['trio-demo','velvet-demo','apex-demo','muse-demo'];
 const state={me:null,slug:null,business:null,screen:'overview',authMode:'login',guest:null,station:null,cart:[],requestFilter:'all',requestKind:'',requestLead:'',requestSearch:'',requestStation:'',requestPage:null,requestCursor:null,requestHistory:[],requestGeneration:0,workMarkup:null,requestLoading:false,requestError:'',guestSearch:'',guestCategory:'',guestDraft:{},pending:false,feedback:'',guestOrigin:'landing',poll:null,guestPoll:null,qr:null,receipt:null,receipts:[],inviteToken:null,inviteUrl:''};
 const newRequestKey=()=>{if(crypto?.randomUUID)return crypto.randomUUID();const b=new Uint8Array(24);crypto.getRandomValues(b);return Array.from(b).map(v=>v.toString(16).padStart(2,'0')).join('')};
 const xss=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const fmt=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format((n||0)/100);
 const datetime=t=>new Date(t*1000).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
 const shorten=s=>String(s||'').slice(0,36);
 const pill=s=>`<span class="status ${s}">${({open:'NEW',in_progress:'IN PROGRESS',completed:'COMPLETED'})[s]||xss(s)}</span>`;
 function toast(message){const box=document.createElement('div');box.className='toast';box.textContent=message;$('toasts').append(box);setTimeout(()=>box.remove(),3700)}
 function section(id){for(const n of ['landing','appShell','guestShell'])$(n).classList.toggle('hidden',id!==n)}
 function showIntro(){let done=false;try{done=sessionStorage.getItem('scene-intro-seen')==='yes'}catch{};const close=()=>{$('intro').classList.add('closed');try{sessionStorage.setItem('scene-intro-seen','yes')}catch{}};$('introSkip').onclick=close;if(done||matchMedia('(prefers-reduced-motion: reduce)').matches)close();else setTimeout(close,2900)}
 async function api(path,opts={}){const headers={'Accept':'application/json',...(opts.body?{'Content-Type':'application/json'}:{}),...(opts.method&&opts.method!=='GET'&&state.me?{'x-scene-csrf':state.me.csrf}:{})};let res;try{res=await fetch(path,{credentials:'same-origin',...opts,headers:{...headers,...(opts.headers||{})}})}catch{throw new Error('Cannot connect to SCENE. Check that the server is running.')}let payload={};try{payload=await res.json()}catch{}if(!res.ok)throw new Error(typeof payload.detail==='string'?payload.detail:`Request failed (${res.status})`);return payload}
 function authOpen(mode='login'){state.authReturnFocus=document.activeElement;$('authModal').classList.remove('hidden');document.body.style.overflow='hidden';setAuthMode(mode);$('authEmail').focus()}
 function authClose(){$('authModal').classList.add('hidden');document.body.style.overflow='';state.authReturnFocus?.focus()}
 function setAuthMode(mode){state.authMode=mode;let creating=mode==='signup';$('authBusiness').required=creating;$('signupExtras').classList.toggle('hidden',!creating);$('authTitle').textContent=creating?'Build your experience.':'Welcome back.';$('authEyebrow').textContent=creating?'GET STARTED / STEP 01':'OWNER ACCESS';$('authDesc').textContent=creating?'Create your business workspace in less than a minute.':'Get back to building unforgettable experiences.';$('authSubmit').textContent=creating?'Create my workspace ↗':'Sign in ↗';$('switchAuth').textContent=creating?'Already registered? Sign in':'New here? Create your business account';$('authPassword').autocomplete=creating?'new-password':'current-password';$('authError').classList.add('hidden')}
 async function login(email,password){await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});await initWorkspace();authClose();toast('Welcome to SCENE ✦')}
 async function signup(){const email=$('authEmail').value.trim(),password=$('authPassword').value,name=$('authBusiness').value.trim(),industry=$('authIndustry').value;await api('/api/auth/signup',{method:'POST',body:JSON.stringify({email,password,name,industry})});await initWorkspace();authClose();toast('Your new workspace is ready ✓')}
 async function initWorkspace(){state.me=await api('/api/me');if(!state.me.businesses.length)throw new Error('Your account has no businesses');state.slug=state.slug&&state.me.businesses.some(b=>b.slug===state.slug)?state.slug:state.me.businesses[0].slug;$$('#businessSelect option').forEach(e=>e.remove());for(const b of state.me.businesses){const o=document.createElement('option');o.value=b.slug;o.textContent=b.name;$('businessSelect').append(o)}$('businessSelect').value=state.slug;$('footerAccount').textContent=state.me.email;await loadBusiness(state.slug);section('appShell');showScreen('overview');beginPolling()}
 async function loadBusiness(slug){
  if(state.slug!==slug||state.business?.slug!==slug){state.inviteUrl='';state.requestPage=null;state.requestFilter='all';state.requestSearch='';state.requestKind='';state.requestLead='';state.requestStation='';resetRequestPaging()}
  if(state.business?.slug!==slug){state.business=null;state.workMarkup=null;$('workContent').textContent='Loading workspace…'}
  state.slug=slug;
  const business=await api('/api/admin/'+encodeURIComponent(slug));
  if(state.slug!==slug||!state.me)return;
  state.business=business;
  $('businessSelect').value=slug;
  const role=business.role;
  $$('#mainNav [data-screen]').forEach(btn=>{btn.classList.toggle('hidden',role==='staff'&&!['overview','requests'].includes(btn.dataset.screen)||btn.dataset.screen==='team'&&role!=='owner')});
  if(role==='staff'&&!['overview','requests'].includes(state.screen)||state.screen==='team'&&role!=='owner')state.screen='overview';
  if(role==='owner'){
   try{const [team,pending]=await Promise.all([api(`/api/admin/${encodeURIComponent(slug)}/members`),api(`/api/admin/${encodeURIComponent(slug)}/invites`)]);if(state.business!==business)return;business.members=team.members;business.pendingInvites=pending.invites}
   catch(e){business.teamError=e.message}
  }
  if(state.screen==='requests')await loadRequests(false);
  if(state.slug===slug&&state.me){$('crumb').textContent=TITLES[state.screen]||state.screen;$$('#mainNav .nav-button').forEach(button=>button.classList.toggle('active',button.dataset.screen===state.screen));renderWorkspace()}
 }
 function beginPolling(){if(state.poll)clearInterval(state.poll);state.poll=setInterval(async()=>{if(!state.me||document.hidden||$('appShell').classList.contains('hidden'))return;try{if(['overview','requests','analytics'].includes(state.screen)&&!qs('.request-tools')?.contains(document.activeElement)&&!qs('[data-status-id]:focus,[data-lead-id]:focus'))await loadBusiness(state.slug)}catch(e){toast(e.message)}},6500)}
 function closeSidebar(){$('sidebar').classList.remove('visible');$('sidebarCurtain').classList.add('hidden')}
 function showScreen(screen){if(state.business?.role==='staff'&&!['overview','requests'].includes(screen))screen='requests';if(screen==='team'&&state.business?.role!=='owner')screen='overview';state.screen=screen;$$('#mainNav .nav-button').forEach(b=>b.classList.toggle('active',b.dataset.screen===screen));$('crumb').textContent=TITLES[screen]||screen;closeSidebar();renderWorkspace();if(screen==='requests')loadRequests();window.scrollTo({top:0,behavior:'smooth'})}
 const guestLink=token=>`${location.origin}/q/${encodeURIComponent(token)}`;
 function updateBubble(){const c=state.business?.analytics?.open||0;$('reqBubble').textContent=c;$('reqBubble').classList.toggle('hidden',!c)}
 function heading(label,title,sub,action=''){return `<div class="screen-label">${label}</div><div class="heading-row"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
 function renderWorkspace(){if(!state.business||!state.me)return;updateBubble();let html='';switch(state.screen){case 'overview':html=renderOverview();break;case 'requests':html=renderRequests();break;case 'catalog':html=renderCatalog();break;case 'stations':html=renderStations();break;case 'analytics':html=renderAnalytics();break;case 'settings':html=renderSettings();break;case 'team':html=renderTeam();break} if(state.workMarkup!==html){$('workContent').innerHTML=html;state.workMarkup=html;bindScreen()}}
 function renderOverview(){const b=state.business,analytics=b.analytics,open=b.requests.filter(r=>r.status!=='completed');return `
  ${heading('BUSINESS COMMAND CENTER','Your experience. Under control.','Everything happening across '+xss(b.name)+' in one beautiful workspace.',`<button class="btn btn-ghost" data-action="preview">Preview customer view ↗</button>`)}
  <div class="hero-panel"><div><div class="screen-label">✦ SCENE / ${xss(b.industry.toUpperCase())}</div><h2>Make every visit<br><em>worth remembering.</em></h2><p>Your QR-powered experience is ready. Customers can scan a real location QR code to browse the catalog and send a staff request.</p><button class="btn btn-primary" data-action="preview">Launch experience ↗</button></div><div class="hero-illustration"><div class="floor-map"><div class="map-table t1">01</div><div class="map-table t2">02</div><div class="map-table t3">03</div></div></div></div>
  <div class="stats-grid"><div class="stat-card"><span>Total requests</span><b>${analytics.total}</b><small>Requests received</small></div><div class="stat-card"><span>New requests</span><b>${analytics.open}</b><small>Waiting for attention</small></div><div class="stat-card"><span>Completed</span><b>${analytics.resolved}</b><small>Handled by staff</small></div><div class="stat-card"><span>QR scans</span><b>${analytics.scans}</b><small>${b.stations.length} QR locations</small></div></div>
  <div class="two-cols"><div class="panel"><div class="panel-title"><h3>Recent customer activity</h3><button class="smallbtn" data-action="requests">View all →</button></div>${open.length?open.slice(0,5).map(r=>activityRow(r)).join(''):'<div class="empty-state">No pending requests. Open the customer experience and try a service request to see it here.</div>'}</div><div class="panel"><div class="panel-title"><h3>Quick launch</h3><span class="hint">ONE TAP AWAY</span></div><div class="quick-buttons"><button data-action="preview"><span>↗</span>Customer preview</button><button data-action="stations"><span>▦</span>QR code manager</button>${b.role!=='staff'?'<button data-action="catalog"><span>▤</span>Edit catalog</button><button data-action="settings"><span>✦</span>Brand studio</button>':''}</div><div class="warn-note section-gap">${xss(b.industry)} demo: customer submissions create staff requests, not paid or confirmed orders.</div></div></div>`}
 function activityRow(r){return `<div class="activity-row"><div class="activity-icon">${r.kind==='order'?'🛍️':'⌁'}</div><div class="activity-info"><b>${xss(r.kind.replace('_',' ').toUpperCase())} · ${xss(r.station)}</b><span>${xss(r.message||'Customer needs assistance')} · ${datetime(r.created_at)}</span></div>${pill(r.status)}</div>`}
 function resetRequestPaging(){state.requestCursor=null;state.requestHistory=[]}
 async function loadRequests(render=true){
  if(!state.business||!state.me)return;
  const slug=state.slug,generation=++state.requestGeneration;
  const params=new URLSearchParams({status:state.requestFilter,limit:'25'});
  if(state.requestKind)params.set('kind',state.requestKind);
  if(state.requestLead)params.set('lead_status',state.requestLead);
  if(state.requestSearch)params.set('search',state.requestSearch);
  if(state.requestStation)params.set('station_id',state.requestStation);
  if(state.requestCursor)params.set('before',state.requestCursor);
  state.requestLoading=true;state.requestError='';
  try{const page=await api(`/api/admin/${encodeURIComponent(slug)}/requests?${params}`);if(state.slug!==slug||generation!==state.requestGeneration)return;state.requestPage=page}
  catch(e){if(state.slug!==slug||generation!==state.requestGeneration)return;state.requestError=e.message}
  if(generation!==state.requestGeneration||state.slug!==slug)return;
  state.requestLoading=false;if(render&&state.screen==='requests')renderWorkspace();
 }
 function requestCard(r){return `<div class="request-card"><div class="activity-icon">${r.kind==='order'?'🛍️':'🔔'}</div><div class="request-body"><b>${xss(r.kind.replace('_',' ').toUpperCase())} · ${xss(r.station)}</b><p>${xss(r.message||'Customer requested assistance')}</p>${r.customer_name||r.customer_contact?`<p>${xss(r.customer_name||'Guest')} · ${xss(r.customer_contact||'No contact supplied')}</p>`:''}${r.product_name?`<p>${r.quantity} × ${xss(r.product_name)} · ${r.unit_price_cents?fmt(r.quantity*r.unit_price_cents)+' estimate':'Quote required'}</p>`:''}${r.kind==='question'?`<label>Lead stage <select data-lead-id="${r.id}" aria-label="Lead stage for request ${r.id}" ${state.business.role==='staff'?'disabled':''}>${!r.lead_status?'<option value="" selected>Unreviewed</option>':''}${['new','qualified','closed'].map(stage=>`<option value="${stage}" ${r.lead_status===stage?'selected':''}>${stage}</option>`).join('')}</select></label>`:''}<small>${datetime(r.created_at)} · #${r.id}</small></div>${pill(r.status)}${r.status==='completed'?'<span class="hint">✓ Done</span>':`<select aria-label="Update status for request ${r.id}" data-status-id="${r.id}"><option value="" selected>Update status</option>${r.status==='open'?'<option value="in_progress">In progress</option>':''}<option value="completed">Completed</option></select>`}</div>`}
 function renderRequests(){
  const b=state.business,page=state.requestPage,rows=page?.requests||[],counts=page?.status_counts||{all:0,open:0,in_progress:0,completed:0};
  const kinds=[...new Set((ACTIONS[b.industry]||[]).map(a=>a[2]).concat(['restaurant','retail'].includes(b.industry)?['order']:[]))];
  return `${heading('SERVICE COMMAND','Request center','Find customer inquiries and service requests across your full history.',`<button class="btn btn-ghost" data-action="refresh">↻ Refresh</button>`)}
   <div class="panel"><form id="requestSearchForm" class="request-tools">
    <div class="form-field"><label for="requestSearch">SEARCH MESSAGES, CONTACTS OR STATIONS</label><input class="field" type="search" id="requestSearch" maxlength="100" value="${xss(state.requestSearch)}" placeholder="e.g. contact or front desk"></div>
    <div class="form-field"><label for="requestKind">REQUEST TYPE</label><select class="field" id="requestKind"><option value="">All types</option>${kinds.map(k=>`<option value="${k}" ${state.requestKind===k?'selected':''}>${k==='question'?'Questions / inquiries':xss(k.replace('_',' '))}</option>`).join('')}</select></div>
    <div class="form-field"><label for="requestLead">LEAD STAGE</label><select class="field" id="requestLead"><option value="">All requests</option>${Object.entries({new:"New inquiries",qualified:"Qualified inquiries",closed:"Closed inquiries",unreviewed:"Unreviewed legacy inquiries"}).map(([value,label])=>`<option value="${value}" ${state.requestLead===value?"selected":""}>${label}</option>`).join('')}</select></div>
    <div class="form-field"><label for="requestStation">STATION</label><select class="field" id="requestStation"><option value="">All stations</option>${b.stations.map(spot=>`<option value="${spot.id}" ${String(spot.id)===state.requestStation?'selected':''}>${xss(spot.label)}</option>`).join('')}</select></div>
    <button type="submit" class="btn btn-primary">Apply filters</button><button type="button" class="btn btn-ghost" id="clearRequestFilters">Reset</button>
   </form>
   <div class="filter-row">${Object.entries({all:'All requests',open:'New',in_progress:'In progress',completed:'Completed'}).map(([k,label])=>`<button class="chip ${state.requestFilter===k?'active':''}" data-filter="${k}" aria-pressed="${state.requestFilter===k}">${label} · ${counts[k]}</button>`).join('')}</div>
   ${state.requestError?`<p class="auth-error" role="alert">${xss(state.requestError)}. Use Refresh to try again.</p>`:''}
   <div class="request-list" aria-busy="${state.requestLoading}">${rows.length?rows.map(requestCard).join(''):`<div class="empty-state">${!page&&!state.requestError?'Loading requests…':'No requests match these filters.'}</div>`}</div>
   <nav class="request-pages" aria-label="Request history pages"><button class="btn btn-ghost" id="previousRequests" ${!state.requestHistory.length||state.requestLoading?'disabled':''}>← Previous</button><span role="status">Page ${state.requestHistory.length+1} · ${page?.total||0} matching requests</span><button class="btn btn-ghost" id="nextRequests" ${!page?.has_more||state.requestLoading?'disabled':''}>Next →</button></nav></div>
   <p class="form-helper section-gap">Newest first, 25 per page. Type, lead stage, station and search filters apply to the full history. Questions / inquiries includes messages with optional contact details; these are requests, not confirmed sales.</p>`
 }
 function renderCatalog(){const b=state.business;return `${heading('WHAT CUSTOMERS SEE','Manage your catalog','Add products or services for your '+xss(b.industry)+' experience. Prices are illustrative, not checkout-enabled.',`<button class="btn btn-ghost" data-action="preview">View guest catalog ↗</button>`)}<div class="two-cols"><div class="panel"><div class="panel-title"><h3>Available items / services</h3><span class="tag">${b.products.length} published</span></div>${b.products.length?b.products.map((p,i)=>`<div class="catalog-row"><div class="catalog-emoji">${getItemEmoji(b.industry,i)}</div><div class="row-main"><b>${xss(p.name)}</b><small>${xss(p.description)} · ${xss(p.category)}</small></div><span class="price">${p.price_cents?fmt(p.price_cents):'Quote'}</span><button class="smallbtn danger-btn" data-delete-product="${p.id}" aria-label="Remove ${xss(p.name)}">Remove</button></div>`).join(''):'<div class="empty-state">Your catalog is empty. Add the first service on the right.</div>'}</div><div class="panel"><div class="panel-title"><h3>✦ Add a new item</h3></div><form id="productForm" class="fields-grid"><div class="form-field wide"><label for="prodName">ITEM NAME</label><input id="prodName" class="field" maxlength="90" required placeholder="Signature service"></div><div class="form-field wide"><label for="prodDesc">DESCRIPTION</label><input id="prodDesc" class="field" maxlength="250" placeholder="What makes it special?"></div><div class="form-field"><label for="prodCat">CATEGORY</label><input id="prodCat" class="field" maxlength="40" value="Featured" required></div><div class="form-field"><label for="prodPrice">PRICE (USD)</label><input id="prodPrice" class="field" min="0" max="100000" step="0.01" type="number" placeholder="e.g. 24.00" value="0" required></div><div class="form-field wide"><button class="btn btn-primary" type="submit">Add to catalog ↗</button></div></form><p class="form-helper section-gap">The customer can send interest to the team. Integration with POS, inventory, or payments comes later.</p></div></div>`}
 function getItemEmoji(industry,index){return({restaurant:['🍟','🍔','🥩','🥂','🍰'],barber:['✂️','🪒','💈'],auto:['🚘','🧽','✨'],retail:['🧥','👜','👟']}[industry]||['✨'])[index%(({restaurant:5,barber:3,auto:3,retail:3})[industry]||1)]}
 function renderStations(){const b=state.business;return `${heading('YOUR QR NETWORK','QR stations','Each table, chair, service bay, or shop zone has its own scannable entry point.',`<button class="btn btn-ghost" data-action="preview">Test any station ↗</button>`)}<div class="panel"><div class="panel-title"><h3>Connected scan locations</h3><span class="tag">${b.stations.length} stations</span></div><div class="qr-grid">${b.stations.map(s=>`<div class="qr-card"><img loading="lazy" class="qr-image" alt="QR code for ${xss(s.label)}" src="/api/qr/${encodeURIComponent(s.token)}.png"><h4>${xss(s.label)}</h4><p>${xss(b.slug)} / ${xss(s.code)}</p><div class="qr-actions"><button class="smallbtn" data-station-preview="${xss(s.token)}">Preview</button><button class="smallbtn" data-copy-station="${xss(s.token)}">Copy link</button><a class="smallbtn" href="/api/qr/${encodeURIComponent(s.token)}.png" download="SCENE-${xss(b.slug)}-${xss(s.code)}.png">Download QR</a><button class="smallbtn" data-rotate-station="${s.id}">Rotate ↻</button></div></div>`).join('')}</div><hr class="divider"><form id="stationForm" class="fields-grid" style="max-width:650px"><div class="form-field"><label for="newStation">NEW STATION LABEL</label><input id="newStation" class="field" required minlength="2" maxlength="70" placeholder="e.g. Table 05 or Bay 03"></div><div class="form-field" style="align-self:end"><button class="btn btn-primary" type="submit">Create station ↗</button></div></form><p class="form-helper section-gap">A downloaded QR code is permanent as long as its business and station identifier remain active. Host SCENE on HTTPS before printing production signs.</p></div>`}
 function renderAnalytics(){let b=state.business,a=b.analytics,total=a.total||0,done=a.resolved||0,ratio=total?Math.round(done/total*100):0;const bykind=a.request_kinds||{};return `${heading('BUSINESS INTELLIGENCE','Interaction analytics','Understand how customers use your experience. Each guest page load is counted as a scan; counts may include repeat visits.')}
  <div class="analytics-grid"><div class="panel"><div class="screen-label">QR SCANS</div><div class="metric-big">${a.scans}</div><p class="form-helper">Lifetime for this business</p></div><div class="panel"><div class="screen-label">REQUESTS COMPLETED</div><div class="metric-big">${done}</div><p class="form-helper">Handled by your team</p></div><div class="panel"><div class="screen-label">COMPLETION RATE</div><div class="metric-big">${ratio}%</div><p class="form-helper">Of all submitted requests</p></div></div>
  <div class="two-cols section-gap"><div class="panel"><div class="panel-title"><h3>Request types</h3></div>${Object.keys(bykind).length?Object.entries(bykind).sort((a,b)=>b[1]-a[1]).map(([kind,count])=>`<div style="margin:16px 0"><div class="panel-title" style="margin-bottom:7px"><span>${xss(kind.toUpperCase())}</span><strong>${count}</strong></div><div class="progressbar"><span style="width:${Math.round(count/total*100)}%"></span></div></div>`).join(''):'<div class="empty-state">Customer requests will appear here when guests interact with your QR system.</div>'}</div><div class="panel"><h3>Activity by station</h3><div class="table-scroll"><table class="analytics-table"><thead><tr><th scope="col">Station</th><th scope="col">Page loads</th><th scope="col">Requests</th></tr></thead><tbody>${(a.stations||[]).map(s=>`<tr><th scope="row">${xss(s.label)}</th><td>${s.scans}</td><td>${s.requests}</td></tr>`).join('')}</tbody></table></div><h3 class="section-gap">Last 7 days · UTC</h3><div class="table-scroll"><table class="analytics-table"><thead><tr><th scope="col">Date</th><th scope="col">Page loads</th><th scope="col">Requests</th></tr></thead><tbody>${(a.daily||[]).map(d=>`<tr><th scope="row">${new Date(d.day*1000).toISOString().slice(5,10)}</th><td>${d.scans}</td><td>${d.requests}</td></tr>`).join('')}</tbody></table></div><h3 class="section-gap">Data quality, first.</h3><p class="form-helper" style="line-height:1.9">Counts cover all recorded activity for this business. Page loads include previews, refreshes and automated traffic; they are not unique visitors. Requests are staff interactions, not sales or revenue.</p><div class="warn-note section-gap">Your data stays scoped to this business account. Analytics are operational estimates, not sales reports.</div></div></div>`}
 function renderSettings(){let b=state.business;return `${heading('YOUR BRAND, YOUR WORLD','Experience studio','Choose how your business appears to guests who scan your code.',`<button class="btn btn-ghost" data-action="preview">Preview changes ↗</button>`)}<div class="two-cols"><div class="panel"><div class="panel-title"><h3>Brand configuration</h3></div><form id="settingsForm" class="fields-grid"><div class="form-field wide"><label for="settingName">BUSINESS NAME</label><input id="settingName" class="field" value="${xss(b.name)}" minlength="2" maxlength="80" required></div><div class="form-field wide"><label for="settingTag">GUEST WELCOME MESSAGE</label><input id="settingTag" class="field" value="${xss(b.tagline)}" maxlength="120" placeholder="Your next experience starts here"></div><div class="form-field"><label for="settingAccent">ACCENT COLOR</label><input id="settingAccent" type="color" class="field" value="${xss(b.accent)}" style="height:46px;cursor:pointer"></div><div class="form-field"><label>INDUSTRY</label><input class="field" disabled value="${xss(b.industry.toUpperCase())}"></div><div class="form-field wide"><button class="btn btn-primary" type="submit">Save experience ↗</button></div></form></div><div class="panel"><div class="panel-title"><h3>Guest first impression</h3></div><div style="border-radius:17px;padding:26px;min-height:226px;background:radial-gradient(ellipse at right,${xss(b.accent)}58,transparent),linear-gradient(140deg,#3b2933,#1c1a27)"><div class="screen-label">WELCOME / ${xss(b.industry.toUpperCase())}</div><h2 style="font-size:36px;letter-spacing:-.05em;margin-bottom:6px">${xss(b.name)}</h2><p style="font-size:12px;color:#ded0d3;line-height:1.8">${xss(b.tagline||'Your next experience starts here.')}</p></div><div class="warn-note section-gap">Custom colors and catalog edits are saved. Advanced 3D interiors, custom domains, AI and POS sync are on the roadmap.</div></div></div>`}
 function bindScreen(){const root=$('workContent'),slug=state.business.slug;
  if($('requestSearchForm'))$('requestSearchForm').onsubmit=e=>{e.preventDefault();state.requestSearch=$('requestSearch').value.trim();state.requestKind=$('requestKind').value;state.requestLead=$('requestLead').value;state.requestStation=$('requestStation').value;resetRequestPaging();loadRequests()};
  if($('clearRequestFilters'))$('clearRequestFilters').onclick=()=>{state.requestSearch='';state.requestKind='';state.requestLead='';state.requestStation='';state.requestFilter='all';state.workMarkup=null;resetRequestPaging();loadRequests()};
  if($('nextRequests'))$('nextRequests').onclick=()=>{if(state.requestLoading||!state.requestPage?.has_more)return;state.requestHistory.push(state.requestCursor);state.requestCursor=state.requestPage.next_before;loadRequests()};
  if($('previousRequests'))$('previousRequests').onclick=()=>{if(state.requestLoading||!state.requestHistory.length)return;state.requestCursor=state.requestHistory.pop();loadRequests()};
  $$('[data-revoke-invite]',root).forEach(button=>button.onclick=async()=>{button.disabled=true;try{await api(`/api/admin/${slug}/invites/${button.dataset.revokeInvite}/revoke`,{method:'POST',body:'{}'});if(state.slug!==slug)return;state.inviteUrl='';await loadBusiness(slug);toast('Invitation revoked')}catch(e){toast(e.message);button.disabled=false}});
 $$('[data-lead-id]',root).forEach(select=>select.onchange=async()=>{select.disabled=true;try{await api(`/api/admin/${slug}/requests/${select.dataset.leadId}/lead`,{method:'PATCH',body:JSON.stringify({status:select.value})});await loadBusiness(state.slug);toast('Lead stage updated')}catch(e){toast(e.message);select.disabled=false}});$$('[data-member-role]',root).forEach(select=>select.onchange=async()=>{select.disabled=true;try{await api(`/api/admin/${slug}/members/${select.dataset.memberRole}`,{method:'PATCH',body:JSON.stringify({role:select.value})});await loadBusiness(state.slug);toast('Team role updated')}catch(e){toast(e.message);select.disabled=false}});$$('[data-revoke-member]',root).forEach(button=>button.onclick=async()=>{if(!confirm('Remove this teammate from this business? Access will stop immediately.'))return;button.disabled=true;try{await api(`/api/admin/${slug}/members/${button.dataset.revokeMember}`,{method:'DELETE'});await loadBusiness(state.slug);toast('Business access removed')}catch(e){toast(e.message);button.disabled=false}});$$('[data-action]',root).forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==='preview')openGuest(state.business.stations[0]?.token,'dashboard');else if(a==='refresh')loadBusiness(state.slug).catch(e=>toast(e.message));else showScreen(a)});$$('[data-filter]',root).forEach(b=>b.onclick=()=>{state.requestFilter=b.dataset.filter;resetRequestPaging();loadRequests()});$$('[data-status-id]',root).forEach(s=>s.onchange=async()=>{s.disabled=true;try{await api(`/api/admin/${slug}/requests/${s.dataset.statusId}`,{method:'PATCH',body:JSON.stringify({status:s.value})});await loadBusiness(state.slug);toast('Request updated ✓')}catch(e){toast(e.message);s.disabled=false}});$$('[data-delete-product]',root).forEach(b=>b.onclick=async()=>{if(!confirm('Remove this item from your public catalog?'))return;try{await api(`/api/admin/${slug}/products/${b.dataset.deleteProduct}`,{method:'DELETE'});await loadBusiness(state.slug);toast('Item unpublished')}catch(e){toast(e.message)}});$$('[data-station-preview]',root).forEach(b=>b.onclick=()=>openGuest(b.dataset.stationPreview,'dashboard'));$$('[data-copy-station]',root).forEach(b=>b.onclick=()=>copyText(guestLink(b.dataset.copyStation)));if($('productForm'))$('productForm').onsubmit=async e=>{e.preventDefault();const dollars=Number($('prodPrice').value);if(!Number.isFinite(dollars)||dollars<0){toast('Enter a valid price');return}const data={name:$('prodName').value.trim(),description:$('prodDesc').value.trim(),category:$('prodCat').value.trim(),price_cents:Math.round(dollars*100)};await sendForm('productForm',()=>api(`/api/admin/${slug}/products`,{method:'POST',body:JSON.stringify(data)}),'Item added to catalog')};$$('[data-rotate-station]',root).forEach(btn=>btn.onclick=async()=>{if(!confirm('Rotate this QR? The old printed code will stop working.'))return;try{await api(`/api/admin/${slug}/stations/${btn.dataset.rotateStation}/rotate`,{method:'POST',body:'{}'});await loadBusiness(state.slug);toast('QR rotated. Print the replacement code.') }catch(e){toast(e.message)}});if($('inviteForm'))$('inviteForm').onsubmit=async e=>{e.preventDefault();try{const data=await api(`/api/admin/${slug}/invites`,{method:'POST',body:JSON.stringify({role:$('inviteRole').value})});if(state.slug!==slug)return;state.inviteUrl=data.join_url;await loadBusiness(slug);toast('Single-use invite link created')}catch(err){toast(err.message)}};if($('copyInvite'))$('copyInvite').onclick=()=>copyText(state.inviteUrl);if($('stationForm'))$('stationForm').onsubmit=async e=>{e.preventDefault();await sendForm('stationForm',()=>api(`/api/admin/${slug}/stations`,{method:'POST',body:JSON.stringify({label:$('newStation').value.trim()})}),'New QR station created')};if($('settingsForm'))$('settingsForm').onsubmit=async e=>{e.preventDefault();await sendForm('settingsForm',()=>api(`/api/admin/${slug}/settings`,{method:'PATCH',body:JSON.stringify({name:$('settingName').value.trim(),tagline:$('settingTag').value.trim(),accent:$('settingAccent').value})}),'Brand settings saved')}}
 async function sendForm(id,action,success){const form=$(id),btn=form.querySelector('button[type="submit"]');btn.disabled=true;try{await action();state.workMarkup=null;await loadBusiness(state.slug);toast(success+' ✓')}catch(e){toast(e.message)}finally{btn.disabled=false}}
 async function copyText(s){try{await navigator.clipboard.writeText(s);toast('Customer scan link copied ✓')}catch{prompt('Copy this guest URL:',s)}}
 async function openGuest(token,origin='landing'){if(!token){toast('No active QR location found');return}if(state.pending){toast('Please wait for the current request to finish');return}if(state.guestPoll)clearInterval(state.guestPoll);state.guestPoll=null;state.guestOrigin=origin;state.guestSearch='';state.guestCategory='';state.guestDraft={};state.qr=token;state.cart=[];state.receipt=null;state.receipts=[];try{const saved=JSON.parse(sessionStorage.getItem('scene-receipts:'+token)||'[]');if(Array.isArray(saved))state.receipts=saved.filter(r=>Number.isInteger(r.id)&&typeof r.ticket==='string'&&['open','in_progress','completed'].includes(r.status)).slice(-50)}catch{}state.receipt=state.receipts.at(-1)||null;state.feedback='';state.guest=null;document.body.classList.toggle('standalone-guest',origin==='scan');section('guestShell');$('phoneContent').innerHTML='<div class="loading-phone">Preparing your experience ✦</div>';try{state.guest=await api('/api/q/'+encodeURIComponent(token));state.station=state.guest.stations[0]?.code||null;if(!state.station)throw new Error('This QR location is no longer active');$('guestHeaderLabel').textContent=state.guest.name;renderGuest();beginGuestStatusPolling()}catch(e){$('phoneContent').innerHTML='<div class="loading-phone">'+xss(e.message)+'</div>';toast(e.message)}}
 function matchingProducts(b,search='',category=''){
  const query=search.trim().toLocaleLowerCase();
  return b.products.filter(p=>(!category||p.category===category)&&(!query||[p.name,p.description,p.category].some(v=>String(v||'').toLocaleLowerCase().includes(query))))
 }
 function filterGuestCatalog(){
  const matches=new Set(matchingProducts(state.guest,state.guestSearch,state.guestCategory).map(p=>p.id));
  $$('[data-product-id]',$('phoneContent')).forEach(node=>node.classList.toggle('hidden',!matches.has(Number(node.dataset.productId))));
  if($('guestSearchCount'))$('guestSearchCount').textContent=matches.size?`${matches.size} items shown`:'No items match. Try another search or category.';
 }
 function adjustGuestCart(id,delta){
  if(state.pending)return;
  if(!state.guest?.products.some(p=>p.id===id))return;
  const existing=state.cart.find(item=>item.id===id),quantity=(existing?.qty||0)+delta;
  if(quantity>99){toast('Maximum 99 of each item');return}
  if(quantity<=0)state.cart=state.cart.filter(item=>item.id!==id);
  else if(existing)existing.qty=quantity;
  else state.cart.push({id,qty:quantity});
  renderGuest()
 }
 function renderGuest(){let b=state.guest;if(!b)return;const station=b.stations.find(s=>s.code===state.station),cartTotal=state.cart.reduce((sum,x)=>sum+x.qty,0),subtotal=state.cart.reduce((sum,x)=>sum+x.qty*(b.products.find(p=>p.id===x.id)?.price_cents||0),0);let actions=ACTIONS[b.industry]||ACTIONS.retail;let tpl=`<div class="guest-cover" style="--guest-accent:${xss(b.accent)}"><div class="guest-prehead">✦ POWERED BY SCENE</div><h2>${xss(b.name)}</h2><p>${xss(b.tagline||'Welcome to your next experience.')}</p><div class="guest-spot">⌁ ${xss(station?.label||'Welcome')}</div></div><div class="guest-pad"><h3 class="guest-h">What can we do for you?</h3><p class="guest-sub">Your experience starts right here.</p><div class="guest-actions">${actions.map(([emoji,label,kind])=>`<button class="guest-action" data-kind="${kind}" data-label="${xss(label)}"><span>${emoji}</span>${xss(label)}</button>`).join('')}</div><h3 class="guest-h">${b.industry==='restaurant'?'Explore the menu':b.industry==='barber'?'Explore services':b.industry==='auto'?'Services and upgrades':'Explore the collection'}</h3><p class="guest-sub">Browse items and send your selections for staff confirmation.</p><div class="guest-catalog-tools"><label for="guestSearch">Search the catalog</label><input id="guestSearch" type="search" maxlength="100" value="${xss(state.guestSearch)}" placeholder="Search items or services"><label for="guestCategory">Category</label><select id="guestCategory"><option value="">All categories</option>${[...new Set(b.products.map(p=>p.category))].map(category=>`<option value="${xss(category)}" ${state.guestCategory===category?'selected':''}>${xss(category)}</option>`).join('')}</select><p id="guestSearchCount" role="status"></p></div>${b.products.length?b.products.map((p,i)=>`<div class="guest-product" data-product-id="${p.id}"><div class="guest-product-emoji">${getItemEmoji(b.industry,i)}</div><div class="guest-product-info"><b>${xss(p.name)}</b><p>${xss(p.description)}</p><small>${p.price_cents?fmt(p.price_cents):'Ask for a quote'}</small></div><button data-add="${p.id}" aria-label="Add ${xss(p.name)} to requests">+</button></div>`).join(''):'<div class="guest-feedback">No items have been added yet. Ask staff for assistance above.</div>'}<div class="guest-cart"><h4>My selections · ${cartTotal}</h4><p>Estimated subtotal · staff confirmation required</p>${cartTotal?state.cart.map(item=>{const p=b.products.find(x=>x.id===item.id);return `<div class="cart-line"><p>${item.qty} × ${xss(p?.name||'Item')}</p><div class="quantity-controls"><button data-cart-id="${item.id}" data-cart-delta="-1" aria-label="Decrease ${xss(p?.name)} quantity" ${state.pending?'disabled':''}>−</button><span aria-label="Quantity">${item.qty}</span><button data-cart-id="${item.id}" data-cart-delta="1" aria-label="Increase ${xss(p?.name)} quantity" ${item.qty>=99||state.pending?'disabled':''}>+</button></div></div>`}).join(''):'<p>Pick an item or send a direct staff request.</p>'}<div class="guest-cart-actions"><strong>${cartTotal?state.cart.some(item=>!b.products.find(p=>p.id===item.id)?.price_cents)?'Quote required':fmt(subtotal):'No selections'}</strong>${cartTotal?'<button class="alt" data-clear-cart>Clear</button><button data-send-cart>Send to staff ↗</button>':'<button data-help>Request help ↗</button>'}</div></div>${state.feedback?'<div class="guest-feedback">'+xss(state.feedback)+'</div>':''}${state.receipts.length?`<div class="guest-feedback" role="status">${state.receipts.map(r=>`<p>Request #${r.id}: <b ${r===state.receipt?'id="receiptState"':''} data-receipt-id="${r.id}">${xss(r.status.replace('_',' '))}</b></p>`).join('')}Staff updates appear here automatically. Receipts stay in this browser tab for up to 50 requests.</div>`:''}<form id="guestMessageForm" class="guest-message"><h3 class="guest-h">Ask a question</h3><p>Send a message to this business. Add contact details only if you want a reply after your visit.</p><label for="guestNote">Your message</label><textarea id="guestNote" maxlength="200" required rows="3" placeholder="How can the team help?">${xss(state.guestDraft.message||'')}</textarea><label for="guestName">Name (optional)</label><input id="guestName" maxlength="50" autocomplete="name" value="${xss(state.guestDraft.name||'')}"><label for="guestContact">Email or phone (optional)</label><input id="guestContact" maxlength="100" autocomplete="email" value="${xss(state.guestDraft.contact||'')}"><label class="guest-consent"><input id="guestConsent" type="checkbox" ${state.guestDraft.consent?'checked':''}>I agree this business may contact me about this request.</label><button class="btn btn-primary" type="submit">Send message ↗</button><p>Delivered to the staff dashboard. Do not include passwords or payment details.</p></form><p style="font-size:9px;text-align:center;line-height:1.7;color:#8a7e7e;margin:18px 0">Staff confirmation required. This is not a payment or live order.</p></div>`;$('phoneContent').innerHTML=tpl;$$('[data-kind]',$('phoneContent')).forEach(btn=>btn.onclick=()=>{if(btn.dataset.kind==='question'){$('guestMessageForm').scrollIntoView({behavior:'smooth',block:'center'});$('guestNote').focus()}else sendGuestRequest(btn.dataset.kind,btn.dataset.label)});$$('[data-add]',$('phoneContent')).forEach(btn=>btn.onclick=()=>{adjustGuestCart(Number(btn.dataset.add),1)});if($('guestSearch'))$('guestSearch').oninput=event=>{state.guestSearch=event.target.value;filterGuestCatalog()};if($('guestCategory'))$('guestCategory').onchange=event=>{state.guestCategory=event.target.value;filterGuestCatalog()};filterGuestCatalog();$$('[data-cart-id]',$('phoneContent')).forEach(button=>button.onclick=()=>adjustGuestCart(Number(button.dataset.cartId),Number(button.dataset.cartDelta)));for(const [id,key] of [['guestNote','message'],['guestName','name'],['guestContact','contact'],['guestConsent','consent']])if($(id))$(id).oninput=event=>{state.guestDraft[key]=key==='consent'?event.target.checked:event.target.value};if($('guestMessageForm'))$('guestMessageForm').onsubmit=submitGuestMessage;const clear=qs('[data-clear-cart]',$('phoneContent'));if(clear)clear.onclick=()=>{if(state.pending)return;state.cart=[];renderGuest()};const send=qs('[data-send-cart]',$('phoneContent'));if(send)send.onclick=sendCart;const help=qs('[data-help]',$('phoneContent'));if(help)help.onclick=()=>sendGuestRequest(({restaurant:'service',barber:'service',auto:'service',retail:'assistance'})[b.industry],'Guest is requesting help')}
 function qs(selector,root){return root?root.querySelector(selector):document.querySelector(selector)}
 async function sendGuestRequest(kind,label,details={}){if(!state.guest||!state.qr||state.pending)return;state.pending=true;try{const v=await api(`/api/q/${encodeURIComponent(state.qr)}/requests`,{method:'POST',body:JSON.stringify({kind,message:label,client_key:newRequestKey(),...details})});if(kind==='question')state.guestDraft={};rememberReceipt(v);state.feedback='Request sent ✓ The team has been notified. Please wait for staff confirmation.';renderGuest();beginGuestStatusPolling();toast('Staff request received ✓')}catch(e){state.feedback=e.message;if(kind!=='question')renderGuest();toast(e.message)}finally{state.pending=false}}
 async function sendCart(){const b=state.guest,items=[...state.cart];if(!items.length||state.pending)return;state.pending=true;let errors=[],sent=new Set();for(const item of items){const prod=b.products.find(p=>p.id===item.id);if(!prod)continue;try{const v=await api(`/api/q/${encodeURIComponent(state.qr)}/requests`,{method:'POST',body:JSON.stringify({kind:({barber:'service',auto:'service'})[b.industry]||'order',product_id:item.id,quantity:item.qty,message:'Staff confirmation required',client_key:newRequestKey()})});rememberReceipt(v);sent.add(item.id)}catch(e){errors.push(prod.name+': '+e.message)}}state.cart=state.cart.filter(item=>!sent.has(item.id));state.pending=false;if(errors.length){state.feedback='Some items could not be sent: '+errors.join('; ');toast('Some selections were not sent')}else{state.cart=[];state.feedback='Sent to the staff dashboard ✓ These are requests only, not confirmed or paid orders.';toast('Selections sent for staff review ✓')}renderGuest();beginGuestStatusPolling()}
 function closeGuest(){if(state.pending){toast('Please wait for the current request to finish');return}document.body.classList.remove('standalone-guest');if(state.guestPoll)clearInterval(state.guestPoll);state.guestPoll=null;try{history.replaceState({},'',location.pathname)}catch{}if(state.me&&state.guestOrigin==='dashboard'){section('appShell');loadBusiness(state.slug).catch(e=>toast(e.message))}else section('landing')}

 function persistReceipts(){try{sessionStorage.setItem('scene-receipts:'+state.qr,JSON.stringify(state.receipts))}catch{}}
 function rememberReceipt(v){const receipt={id:v.request_id,ticket:v.ticket,status:v.status};state.receipt=receipt;state.receipts=state.receipts.filter(r=>r.id!==receipt.id).concat(receipt).slice(-50);persistReceipts()}
 async function submitGuestMessage(event){
  event.preventDefault();if(state.pending)return;
  const note=$('guestNote'),contact=$('guestContact'),name=$('guestName'),consent=$('guestConsent');
  if(!note.value.trim()){note.setCustomValidity('Enter a message.');note.reportValidity();note.oninput=()=>{note.setCustomValidity('');state.guestDraft.message=note.value};return}
  if(contact.value.trim()&&!consent.checked){consent.setCustomValidity('Please agree before sharing contact details.');consent.reportValidity();consent.onchange=()=>{consent.setCustomValidity('');state.guestDraft.consent=consent.checked};return}
  const button=$('guestMessageForm').querySelector('button');button.disabled=true;
  try{await sendGuestRequest('question',note.value.trim(),{customer_name:name.value.trim(),customer_contact:contact.value.trim(),reply_consent:consent.checked})}finally{button.disabled=false}
 }
 function beginGuestStatusPolling(){
  if(state.guestPoll)clearInterval(state.guestPoll);state.guestPoll=null;
  if(!state.receipts.some(r=>r.status!=='completed'))return;
  const token=state.qr;
  state.guestPoll=setInterval(async()=>{
   if(document.hidden||token!==state.qr)return;
   for(const receipt of state.receipts.filter(r=>r.status!=='completed')){
    try{const r=await api('/api/guest/requests/'+receipt.id,{headers:{'x-scene-ticket':receipt.ticket}});if(token!==state.qr)return;receipt.status=r.status;const node=qs(`[data-receipt-id="${receipt.id}"]`);if(node)node.textContent=r.status.replace('_',' ')}catch{}
   }
   if(token!==state.qr)return;persistReceipts();
   if(state.receipts.every(r=>r.status==='completed')){clearInterval(state.guestPoll);state.guestPoll=null}
  },5500)
 }
 function renderTeam(){const b=state.business;if(b.role!=='owner')return '<div class="empty-state">Owner access required.</div>';return `${heading('MANAGE ACCESS','Your crew. Your platform.','Create a single-use invitation for a staff member or manager.')}<div class="two-cols"><div class="panel"><div class="panel-title"><h3>Invite a teammate</h3></div><p class="form-helper">Invites expire after 24 hours. Staff can see and update requests. Managers can also manage catalog items and QR locations.</p><form id="inviteForm" class="fields-grid"><div class="form-field wide"><label for="inviteRole">PERMISSION LEVEL</label><select class="field" id="inviteRole"><option value="staff">Staff · requests only</option><option value="manager">Manager · edit business setup</option></select></div><div class="form-field wide"><button class="btn btn-primary" type="submit">Generate invite link ↗</button></div></form>${state.inviteUrl?`<div class="guest-feedback"><p style="overflow-wrap:anywhere">${xss(state.inviteUrl)}</p><button id="copyInvite" class="btn btn-ghost">Copy invitation link</button></div>`:''}</div><div class="panel"><h3>Current team</h3>${b.teamError?`<p role="alert">${xss(b.teamError)}</p>`:(b.members||[]).map(m=>`<div class="team-row"><div><b>${xss(m.email)}</b><small>${xss(m.role)}</small></div>${m.role==='owner'?'<span class="tag">Owner</span>':`<select class="field" aria-label="Role for ${xss(m.email)}" data-member-role="${m.id}"><option value="staff" ${m.role==='staff'?'selected':''}>Staff</option><option value="manager" ${m.role==='manager'?'selected':''}>Manager</option></select><button class="smallbtn danger-btn" data-revoke-member="${m.id}">Remove</button>`}</div>`).join('')}<h3 class="section-gap">Pending invitations</h3>${(b.pendingInvites||[]).length?b.pendingInvites.map(inv=>`<div class="team-row"><div><b>${xss(inv.role)}</b><small>Expires ${datetime(inv.expires_at)}</small></div><button class="smallbtn danger-btn" data-revoke-invite="${xss(inv.id)}">Revoke invitation</button></div>`).join(''):'<p class="form-helper">No active unused invitations.</p>'}<h3 class="section-gap">How permissions work</h3><p class="form-helper">The business owns its own data. Staff cannot view other businesses or edit the catalog. Only the owner can create invitations.</p><p class="form-helper">For production, we will add verified email invitations and audit logs.</p></div></div>`}
 function wire(){showIntro();$('openSignIn').onclick=()=>authOpen('login');$('openSignUp').onclick=()=>authOpen('signup');$('launchDashboard').onclick=()=>state.me?initWorkspace().catch(e=>toast(e.message)):authOpen('login');$('launchTrio').onclick=async()=>{try{const d=await api('/api/demo/trio-demo');await openGuest(d.q,'landing')}catch{authOpen('signup');toast('Create your space to preview the QR flow.')}};$('authClose').onclick=authClose;$('authModal').onclick=e=>{if(e.target===$('authModal'))authClose()};$('switchAuth').onclick=()=>setAuthMode(state.authMode==='login'?'signup':'login');$('authForm').onsubmit=async e=>{e.preventDefault();const btn=$('authSubmit');btn.disabled=true;$('authError').classList.add('hidden');try{if(state.inviteToken){await api('/api/auth/join',{method:'POST',body:JSON.stringify({token:state.inviteToken,email:$('authEmail').value.trim(),password:$('authPassword').value})});state.inviteToken=null;try{history.replaceState({},'',location.pathname)}catch{}await initWorkspace();authClose();toast('You joined the team ✓')}else{state.authMode==='signup'?await signup():await login($('authEmail').value,$('authPassword').value)}}catch(e){$('authError').textContent=e.message;$('authError').classList.remove('hidden')}finally{btn.disabled=false}};$('demoSignIn').onclick=async()=>{const btn=$('demoSignIn');btn.disabled=true;try{await login('demo@scene.local','SceneDemo2026!')}catch(e){$('authError').textContent=e.message;$('authError').classList.remove('hidden')}finally{btn.disabled=false}};$('signOut').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:JSON.stringify({})})}catch(e){toast(e.message);return}state.me=null;state.slug=null;state.business=null;state.inviteUrl='';if(state.poll)clearInterval(state.poll);section('landing');toast('You are signed out')};$('businessSelect').onchange=async e=>{try{await loadBusiness(e.target.value)}catch(err){toast(err.message)}};$$('#mainNav [data-screen]').forEach(b=>b.onclick=()=>showScreen(b.dataset.screen));$('mobileMenu').onclick=()=>{$('sidebar').classList.add('visible');$('sidebarCurtain').classList.remove('hidden')};$('closeMobileMenu').onclick=closeSidebar;$('sidebarCurtain').onclick=closeSidebar;$('sidebarPreview').onclick=()=>state.business&&openGuest(state.business.stations[0]?.token,'dashboard');$('exitGuest').onclick=closeGuest;$('staffFromGuest').onclick=()=>state.me?closeGuest():authOpen('login');$('dashLogo').onclick=e=>{e.preventDefault();showScreen('overview')};$('guestBrandLink').onclick=e=>{e.preventDefault();closeGuest()};window.addEventListener('keydown',e=>{if(e.key==='Escape'){authClose();closeSidebar()}if(e.key==='Tab'&&!$('authModal').classList.contains('hidden')){const controls=$$('button,input,select,textarea,a[href]',$('authModal')).filter(n=>!n.disabled&&n.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}})}
 async function initialize(){wire();const search=new URLSearchParams(location.search);if(search.has('q')){await openGuest(search.get('q'),'scan');return}if(search.has('invite')){state.inviteToken=search.get('invite');authOpen('login');$('authTitle').textContent='Join the business team.';$('authEyebrow').textContent='SINGLE-USE TEAM INVITE';$('authDesc').textContent='Enter an existing account and password, or use a new email and password (minimum 10 characters).';$('switchAuth').classList.add('hidden');return}if(search.has('b')){try{const data=await api('/api/demo/'+encodeURIComponent(search.get('b')));await openGuest(data.q,'scan')}catch(e){section('landing');toast(e.message)}return}try{const d=await api('/api/demo/trio-demo');$('demoSignIn').closest('.demo-auth')?.classList.remove('hidden')}catch{$('demoSignIn').closest('.demo-auth')?.classList.add('hidden')}try{state.me=await api('/api/me');if(state.me?.businesses?.length)await initWorkspace();else section('landing')}catch{state.me=null;section('landing')}}
 initialize().catch(e=>{section('landing');toast(e.message)});
})();
